SELECT dc.id, dc.user_id as userId, u.username, dc.title, dc.content, dc.emotion, dc.place, dc.time, dc.created_at as createdAt FROM dream_content dc LEFT JOIN user u ON u.id = dc.user_id
( LOWER(dc.title) LIKE CONCAT('%', LOWER(#{keyword}), '%') OR LOWER(dc.content) LIKE CONCAT('%', LOWER(#{keyword}), '%') OR LOWER(u.username) LIKE CONCAT('%', LOWER(#{keyword}), '%') OR LOWER(dc.place) LIKE CONCAT('%', LOWER(#{keyword}), '%') OR LOWER(dc.emotion) LIKE CONCAT('%', LOWER(#{keyword}), '%') )
ORDER BY dc.created_at DESC LIMIT #{limit} OFFSET #{offset}

